head.b:skin:
    :root {
        --primary: #10b981;
        --primary-dark: #059669;
        --primary-light: #ecfdf5;
        --secondary: #0f172a;
        --secondary-light: #1e293b;
        --text-main: #334155;
        --text-light: #64748b;
        --surface: #fff;
        --bg: #f8fafc;
        --gradient: linear-gradient(135deg, #059669, #10b981);
        --gradient-dark: linear-gradient(135deg, #0f172a, #1e293b);
        --shadow: 0 4px 6px -1px rgba(0, 0, 0, .07), 0 2px 4px -1px rgba(0, 0, 0, .06);
        --shadow-lg: 0 20px 40px -12px rgba(0, 0, 0, .12);
        --radius: 16px;
        --container: 1200px
    }

    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box
    }

    body {
        font-family: 'Outfit', sans-serif;
        color: var(--text-main);
        background: var(--bg);
        line-height: 1.6;
        overflow-x: hidden
    }

    a {
        text-decoration: none;
        color: inherit
    }

    ul {
        list-style: none
    }

    .container {
        max-width: var(--container);
        margin: 0 auto;
        padding: 0 24px
    }

    .btn {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 14px 32px;
        border-radius: 50px;
        font-weight: 600;
        transition: all .3s;
        cursor: pointer;
        font-size: 15px;
        border: none;
        font-family: inherit
    }

    .btn-primary {
        background: var(--gradient);
        color: #fff;
        box-shadow: 0 4px 14px rgba(16, 185, 129, .4)
    }

    .btn-primary:hover {
        transform: translateY(-2px);
        box-shadow: 0 8px 25px rgba(16, 185, 129, .5)
    }

    .btn-outline {
        border: 2px solid var(--primary);
        color: var(--primary);
        background: transparent
    }

    .btn-outline:hover {
        background: var(--primary-light)
    }

    .btn-white {
        background: #fff;
        color: var(--secondary);
        box-shadow: var(--shadow)
    }

    .btn-white:hover {
        transform: translateY(-2px);
        box-shadow: var(--shadow-lg)
    }

    .section-label {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 20px;
        background: var(--primary-light);
        color: var(--primary-dark);
        border-radius: 50px;
        font-size: 13px;
        font-weight: 600;
        margin-bottom: 20px;
        letter-spacing: .5px;
        text-transform: uppercase
    }

    .section-title {
        text-align: center;
        margin-bottom: 60px
    }

    .section-title h2 {
        font-size: 40px;
        font-weight: 800;
        color: var(--secondary);
        margin-bottom: 16px;
        letter-spacing: -.5px
    }

    .section-title p {
        font-size: 18px;
        color: var(--text-light);
        max-width: 600px;
        margin: 0 auto
    }

    /* NAVBAR */
    .navbar {
        padding: 16px 0;
        background: rgba(255, 255, 255, .85);
        backdrop-filter: blur(20px);
        position: fixed;
        width: 100%;
        top: 0;
        z-index: 1000;
        border-bottom: 1px solid rgba(0, 0, 0, .06)
    }

    .navbar .container {
        display: flex;
        justify-content: space-between;
        align-items: center
    }

    .logo {
        font-size: 26px;
        font-weight: 800;
        color: var(--secondary);
        display: flex;
        align-items: center;
        gap: 10px;
        cursor: pointer;
        line-height: 1;
    }

    .navbar .logo {
        transform: translateY(3px);
    }

    .footer .logo {
        transform: translateX(-6px);
    }

    .logo-icon {
        width: 38px;
        height: 38px;
        background: var(--gradient);
        border-radius: 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        color: #fff;
        font-size: 18px
    }

    .nav-links {
        display: flex;
        gap: 32px;
        align-items: center
    }

    .nav-link {
        font-weight: 500;
        color: var(--text-main);
        transition: color .3s;
        cursor: pointer;
        font-size: 15px;
        white-space: nowrap;
    }

    .nav-link:hover {
        color: var(--primary)
    }

    .mobile-menu-btn {
        display: none;
        background: none;
        border: none;
        font-size: 24px;
        cursor: pointer;
        color: var(--secondary)
    }

    /* HERO */
    .hero {
        padding: 140px 0 80px;
        position: relative;
        overflow: hidden
    }

    .hero::before {
        content: '';
        position: absolute;
        top: -50%;
        right: -20%;
        width: 800px;
        height: 800px;
        background: radial-gradient(circle, rgba(16, 185, 129, .08) 0%, transparent 70%);
        border-radius: 50%
    }

    .hero::after {
        content: '';
        position: absolute;
        bottom: -30%;
        left: -10%;
        width: 600px;
        height: 600px;
        background: radial-gradient(circle, rgba(59, 130, 246, .06) 0%, transparent 70%);
        border-radius: 50%
    }

    .hero .container {
        display: grid;
        grid-template-columns: 1fr 1fr;
        align-items: center;
        gap: 60px;
        position: relative;
        z-index: 2
    }

    .hero-content h1 {
        font-size: 58px;
        line-height: 1.08;
        font-weight: 800;
        color: var(--secondary);
        margin-bottom: 24px;
        letter-spacing: -1px
    }

    .hero-content h1 span {
        background: var(--gradient);
        -webkit-background-clip: text;
        background-clip: text;
        -webkit-text-fill-color: transparent
    }

    .hero-content p {
        font-size: 19px;
        color: var(--text-light);
        margin-bottom: 36px;
        max-width: 90%;
        line-height: 1.7
    }

    .hero-buttons {
        display: flex;
        gap: 16px;
        margin-bottom: 40px
    }

    .hero-trust {
        display: flex;
        align-items: center;
        gap: 16px;
        font-size: 14px;
        color: var(--text-light)
    }

    .hero-trust .avatars {
        display: flex
    }

    .hero-trust .avatars span {
        width: 32px;
        height: 32px;
        border-radius: 50%;
        border: 2px solid #fff;
        margin-left: -8px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 11px;
        font-weight: 700;
        color: #fff
    }

    .hero-trust .avatars span:first-child {
        margin-left: 0
    }

    .hero-trust .rating {
        color: #f59e0b
    }

    /* Hero Visual */
    .hero-visual {
        position: relative
    }

    .dashboard-preview {
        background: linear-gradient(160deg, #0f172a 0%, #1a2640 100%);
        border-radius: 20px;
        padding: 20px;
        box-shadow: 0 30px 80px -15px rgba(0, 0, 0, .5), 0 0 0 1px rgba(255, 255, 255, .06);
        position: relative;
        z-index: 2;
        overflow: hidden;
    }

    .dashboard-preview::before {
        content: '';
        position: absolute;
        top: -60px;
        right: -60px;
        width: 180px;
        height: 180px;
        background: radial-gradient(circle, rgba(16, 185, 129, .12), transparent 70%);
        border-radius: 50%;
        pointer-events: none;
    }

    .preview-header {
        display: flex;
        align-items: center;
        gap: 6px;
        margin-bottom: 16px;
    }

    .dot {
        width: 10px;
        height: 10px;
        border-radius: 50%
    }

    .preview-stats {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 10px;
        margin-bottom: 0
    }

    .preview-stat {
        background: rgba(255, 255, 255, .06);
        padding: 12px;
        border-radius: 12px;
        border: 1px solid rgba(255, 255, 255, .08);
        transition: background .3s;
    }

    .preview-stat:hover {
        background: rgba(255, 255, 255, .09);
    }

    .preview-stat .label {
        font-size: 10px;
        color: #94a3b8;
        margin-bottom: 2px;
        font-weight: 500;
        letter-spacing: .3px;
        text-transform: uppercase;
    }

    .preview-stat .val {
        font-size: 17px;
        font-weight: 700;
        color: #fff
    }

    .preview-stat .val.green {
        color: #10b981
    }

    .preview-chart {
        background: rgba(255, 255, 255, .04);
        border-radius: 12px;
        padding: 8px 12px;
        height: 90px;
        position: relative;
        overflow: hidden;
        border: 1px solid rgba(16, 185, 129, .15)
    }

    .preview-chart svg {
        width: 100%;
        height: 100%
    }

    .preview-chart-label {
        font-size: 10px;
        color: #64748b;
        margin: 10px 0 4px;
        letter-spacing: .3px;
    }

    /* Preview URL bar */
    .preview-url-bar {
        flex: 1;
        background: rgba(255, 255, 255, .07);
        border-radius: 6px;
        padding: 4px 10px;
        font-size: 11px;
        color: #94a3b8;
        margin-left: 10px;
        display: flex;
        align-items: center;
        gap: 5px;
    }

    /* Stat icon */
    .stat-icon-wrap {
        width: 28px;
        height: 28px;
        border-radius: 8px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 13px;
        margin-bottom: 6px
    }

    /* Growth badge below stat */
    .stat-badge-up {
        margin-top: 4px;
        font-size: 10px;
        color: #10b981;
        display: flex;
        align-items: center;
        gap: 3px;
    }

    /* Link list inside dashboard preview */
    .preview-links {
        margin-top: 12px;
        display: flex;
        flex-direction: column;
        gap: 6px;
    }

    .preview-link-item {
        display: flex;
        align-items: center;
        gap: 8px;
        background: rgba(255, 255, 255, .05);
        border-radius: 8px;
        padding: 7px 10px;
    }

    .link-dot {
        width: 7px;
        height: 7px;
        border-radius: 50%;
        flex-shrink: 0;
    }

    .link-info {
        flex: 1;
    }

    .link-name {
        font-size: 11px;
        color: #e2e8f0;
        font-weight: 500;
    }

    .link-views {
        font-size: 10px;
        color: #64748b;
    }

    .link-earn {
        font-size: 11px;
        font-weight: 600;
        color: #10b981;
    }

    /* Glow behind card */
    .hero-glow {
        position: absolute;
        bottom: -40px;
        left: 50%;
        transform: translateX(-50%);
        width: 80%;
        height: 60px;
        background: radial-gradient(ellipse at center, rgba(16, 185, 129, .35), transparent 70%);
        filter: blur(20px);
        z-index: 1;
        pointer-events: none;
    }

    .floating-badge {
        position: absolute;
        background: rgba(15, 23, 42, .85);
        backdrop-filter: blur(20px);
        border: 1px solid rgba(255, 255, 255, .1);
        box-shadow: 0 20px 40px -10px rgba(0, 0, 0, .4), 0 0 0 1px rgba(255, 255, 255, .05);
        border-radius: 14px;
        padding: 12px 16px;
        display: flex;
        align-items: center;
        gap: 10px;
        animation: floatBadge 5s ease-in-out infinite;
        z-index: 3
    }

    .floating-badge.b1 {
        top: -15px;
        right: -10px;
        animation-delay: 0s
    }

    .floating-badge.b2 {
        bottom: 20px;
        left: -20px;
        animation-delay: 2.5s
    }

    .floating-badge .badge-icon {
        width: 36px;
        height: 36px;
        border-radius: 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 16px
    }

    .floating-badge .badge-text {
        font-size: 13px;
        font-weight: 600;
        color: #f1f5f9
    }

    .floating-badge .badge-sub {
        font-size: 11px;
        color: #94a3b8
    }

    @keyframes floatBadge {

        0%,
        100% {
            transform: translateY(0)
        }

        50% {
            transform: translateY(-12px)
        }
    }

    /* BRANDS */
    .brands {
        padding: 60px 0;
        border-bottom: 1px solid rgba(0, 0, 0, .06)
    }

    .brands-inner {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 48px;
        flex-wrap: wrap;
        opacity: .4
    }

    .brands-inner span {
        font-size: 22px;
        font-weight: 700;
        color: var(--secondary);
        letter-spacing: 1px
    }

    /* FEATURES */
    .features {
        padding: 100px 0;
        background: #fff
    }

    .features-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 24px
    }

    .feature-card {
        padding: 36px;
        background: var(--bg);
        border-radius: var(--radius);
        transition: all .3s;
        border: 1px solid transparent;
        cursor: default
    }

    .feature-card:hover {
        background: #fff;
        box-shadow: var(--shadow-lg);
        border-color: rgba(16, 185, 129, .15);
        transform: translateY(-6px)
    }

    .feature-icon {
        width: 52px;
        height: 52px;
        border-radius: 14px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 22px;
        margin-bottom: 20px
    }

    .feature-card h3 {
        font-size: 20px;
        margin-bottom: 10px;
        color: var(--secondary);
        font-weight: 700
    }

    .feature-card p {
        color: var(--text-light);
        font-size: 15px;
        line-height: 1.7
    }

    /* HOW IT WORKS */
    .steps {
        padding: 100px 0;
        background: var(--bg)
    }

    .steps-grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 32px;
        position: relative
    }

    .steps-grid::before {
        content: '';
        position: absolute;
        top: 40px;
        left: 12%;
        width: 76%;
        height: 2px;
        background: linear-gradient(90deg, var(--primary), #3b82f6);
        opacity: .2
    }

    .step-card {
        text-align: center;
        position: relative;
        z-index: 2
    }

    .step-num {
        width: 56px;
        height: 56px;
        background: var(--gradient);
        color: #fff;
        border-radius: 16px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: 800;
        font-size: 22px;
        margin: 0 auto 20px;
        box-shadow: 0 8px 20px rgba(16, 185, 129, .3);
        transition: transform .3s
    }

    .step-card:hover .step-num {
        transform: scale(1.1) rotate(-5deg)
    }

    .step-card h3 {
        font-size: 18px;
        margin-bottom: 8px;
        color: var(--secondary)
    }

    .step-card p {
        font-size: 14px;
        color: var(--text-light);
        max-width: 200px;
        margin: 0 auto
    }

    /* EARNINGS TABLE */
    .earnings {
        padding: 100px 0;
        background: #fff
    }

    .earnings-content {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 60px;
        align-items: center
    }

    .earnings-info h2 {
        font-size: 38px;
        font-weight: 800;
        color: var(--secondary);
        margin-bottom: 16px;
        letter-spacing: -.5px
    }

    .earnings-info p {
        font-size: 17px;
        color: var(--text-light);
        margin-bottom: 32px;
        line-height: 1.7
    }

    .earnings-features {
        display: flex;
        flex-direction: column;
        gap: 16px
    }

    .earn-feature {
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 14px 18px;
        background: var(--bg);
        border-radius: 12px;
        transition: all .2s
    }

    .earn-feature:hover {
        background: var(--primary-light)
    }

    .earn-feature i {
        color: var(--primary);
        font-size: 18px;
        width: 20px;
        text-align: center
    }

    .earn-feature span {
        font-size: 15px;
        font-weight: 500
    }

    .rate-table {
        background: var(--secondary);
        border-radius: 20px;
        padding: 32px;
        color: #fff
    }

    .rate-table h3 {
        font-size: 20px;
        margin-bottom: 20px;
        display: flex;
        align-items: center;
        gap: 10px
    }

    .rate-table h3 i {
        color: var(--primary)
    }

    .rate-row {
        display: flex;
        justify-content: space-between;
        padding: 14px 0;
        border-bottom: 1px solid rgba(255, 255, 255, .08);
        font-size: 15px
    }

    .rate-row:last-child {
        border-bottom: none
    }

    .rate-row .country {
        color: #94a3b8
    }

    .rate-row .rate {
        color: var(--primary);
        font-weight: 700
    }

    /* STATS BANNER */
    .stats-banner {
        padding: 80px 0;
        background: var(--gradient-dark);
        position: relative;
        overflow: hidden
    }

    .stats-banner::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")
    }

    .stats-grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 32px;
        text-align: center;
        position: relative;
        z-index: 2
    }

    .stat-item h2 {
        font-size: 44px;
        font-weight: 800;
        color: #fff;
        margin-bottom: 4px
    }

    .stat-item p {
        font-size: 15px;
        color: #94a3b8;
        font-weight: 500
    }

    /* TESTIMONIALS */
    .testimonials {
        padding: 100px 0;
        background: var(--bg)
    }

    .testimonials-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 24px
    }

    .testi-card {
        background: #fff;
        padding: 32px;
        border-radius: var(--radius);
        border: 1px solid rgba(0, 0, 0, .06);
        transition: all .3s
    }

    .testi-card:hover {
        box-shadow: var(--shadow-lg);
        transform: translateY(-4px)
    }

    .testi-stars {
        color: #f59e0b;
        margin-bottom: 16px;
        font-size: 14px
    }

    .testi-text {
        font-size: 15px;
        color: var(--text-main);
        margin-bottom: 20px;
        line-height: 1.7;
        font-style: italic
    }

    .testi-author {
        display: flex;
        align-items: center;
        gap: 12px
    }

    .testi-avatar {
        width: 42px;
        height: 42px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: 700;
        font-size: 15px;
        color: #fff
    }

    .testi-author h4 {
        font-size: 14px;
        font-weight: 600;
        color: var(--secondary)
    }

    .testi-author span {
        font-size: 12px;
        color: var(--text-light)
    }

    /* CTA */
    .cta {
        padding: 100px 0;
        background: #fff
    }

    .cta-box {
        background: var(--gradient-dark);
        border-radius: 24px;
        padding: 64px;
        text-align: center;
        position: relative;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
    }

    .cta-box::before {
        content: '';
        position: absolute;
        top: -50%;
        right: -20%;
        width: 500px;
        height: 500px;
        background: radial-gradient(circle, rgba(16, 185, 129, .15), transparent 70%);
        border-radius: 50%
    }

    .cta-box h2 {
        font-size: 40px;
        font-weight: 800;
        color: #fff;
        margin-bottom: 16px;
        position: relative;
        z-index: 2
    }

    .cta-box p {
        font-size: 18px;
        color: #94a3b8;
        margin-bottom: 36px;
        max-width: 500px;
        margin-left: auto;
        margin-right: auto;
        position: relative;
        z-index: 2
    }

    .cta-box .btn {
        position: relative;
        z-index: 2
    }

    /* FOOTER */
    .footer {
        background: var(--secondary);
        color: #fff;
        padding: 60px 0 20px
    }

    .footer-grid {
        display: grid;
        grid-template-columns: 2fr 1fr 1fr 1fr;
        gap: 40px;
        margin-bottom: 40px
    }

    .footer-brand p {
        color: #94a3b8;
        margin-top: 16px;
        max-width: 280px;
        font-size: 14px;
        line-height: 1.7
    }

    .footer-col h4 {
        font-size: 15px;
        margin-bottom: 20px;
        color: var(--primary);
        font-weight: 600
    }

    .footer-col ul li {
        margin-bottom: 12px
    }

    .footer-col a {
        color: #cbd5e1;
        transition: color .3s;
        cursor: pointer;
        font-size: 14px
    }

    .footer-col a:hover {
        color: #fff
    }

    .footer-social {
        display: flex;
        gap: 12px;
        margin-top: 20px
    }

    .footer-social a {
        height: 36px;
        padding: 0 12px;
        background: rgba(255, 255, 255, .08);
        border-radius: 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        color: #94a3b8;
        transition: all .3s;
        font-size: 14px;
        gap: 8px;
        text-decoration: none;
        width: fit-content;
    }

    .footer-social a:hover {
        background: var(--primary);
        color: #fff
    }

    .footer-bottom {
        padding-top: 20px;
        border-top: 1px solid rgba(255, 255, 255, .08);
        text-align: center;
        color: #64748b;
        font-size: 13px
    }

    /* MODAL */
    .modal-overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(15, 23, 42, .7);
        backdrop-filter: blur(5px);
        opacity: 0;
        pointer-events: none;
        transition: opacity .3s;
        z-index: 2000;
        display: flex;
        align-items: center;
        justify-content: center
    }

    .modal-overlay.active {
        opacity: 1;
        pointer-events: all
    }

    .modal-box {
        background: #fff;
        padding: 40px;
        border-radius: 20px;
        max-width: 400px;
        width: 90%;
        text-align: center;
        transform: translateY(20px);
        transition: transform .3s;
        position: relative
    }

    .modal-overlay.active .modal-box {
        transform: translateY(0)
    }

    .modal-icon {
        width: 60px;
        height: 60px;
        background: var(--primary-light);
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 0 auto 20px;
        color: var(--primary);
        font-size: 24px
    }

    .modal-close {
        position: absolute;
        top: 16px;
        right: 16px;
        background: none;
        border: none;
        font-size: 20px;
        cursor: pointer;
        color: #94a3b8
    }

    /* RESPONSIVE */
    @media(max-width:1024px) {

        .features-grid,
        .steps-grid,
        .stats-grid {
            grid-template-columns: repeat(2, 1fr)
        }

        .earnings-content {
            grid-template-columns: 1fr;
            gap: 40px;
        }

        .footer-grid {
            grid-template-columns: 1fr 1fr
        }

        .hero::before {
            width: 600px;
            height: 600px;
        }
    }

    @media(max-width:768px) {
        body {
            overflow-x: hidden;
        }

        .navbar {
            padding: 12px 0;
        }

        /* Mobile Menu */
        .nav-links {
            display: none;
            flex-direction: column;
            position: absolute;
            top: 100%;
            left: 0;
            width: 100%;
            background: #fff;
            padding: 20px;
            box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1);
            border-top: 1px solid #eee;
            gap: 16px;
            text-align: center;
        }

        .nav-links.active {
            display: flex;
        }

        .nav-links .btn {
            width: 100%;
            justify-content: center;
        }

        .mobile-menu-btn {
            display: block;
            background: none;
            border: none;
            font-size: 24px;
            color: var(--secondary);
            cursor: pointer;
        }

        .hero {
            padding: 120px 0 60px;
        }

        .hero .container {
            grid-template-columns: 1fr;
            text-align: center
        }

        .hero-content h1 {
            font-size: 34px;
            line-height: 1.25;
        }

        .hero-content p {
            font-size: 16px;
            margin: 0 auto 24px;
        }

        .hero-buttons {
            flex-direction: column;
            justify-content: center;
            gap: 12px;
            width: 100%;
            max-width: 300px;
            margin: 0 auto 30px;
        }

        .hero-buttons .btn {
            width: 100%;
            justify-content: center;
        }

        .hero-trust {
            justify-content: center;
        }

        .hero-visual {
            margin-top: 40px;
        }

        /* Grids collapse to 1 column */
        .features-grid,
        .testimonials-grid,
        .steps-grid,
        .stats-grid {
            grid-template-columns: 1fr;
            gap: 24px;
        }

        /* Sections padding reduction */
        .features,
        .steps,
        .earnings,
        .testimonials,
        .cta,
        .stats-banner {
            padding: 60px 0;
        }

        .cta-box {
            padding: 40px 24px;
        }

        .cta-box h2 {
            font-size: 28px;
        }

        .footer-grid {
            grid-template-columns: 1fr;
            gap: 30px;
        }

        .section-title h2 {
            font-size: 28px;
        }

        .section-title {
            margin-bottom: 40px;
        }

        .rate-table {
            padding: 20px;
        }

        .earnings-info h2 {
            font-size: 28px;
        }

        /* Remove steps horizontal line on mobile */
        .steps-grid::before {
            display: none;
        }
    }

    /* SPA VIEW LOGIC */
    .page-view {
        display: none;
        animation: fadeInPage 0.3s;
    }

    .page-view.active {
        display: block;
    }

    @keyframes fadeInPage {
        from {
            opacity: 0;
        }

        to {
            opacity: 1;
        }
    }

    .page-header {
        padding: 120px 0 60px;
        text-align: center;
        background: var(--gradient-dark);
        color: #fff;
    }

    .page-content {
        padding: 60px 0;
        background: #fff;
        min-height: 500px;
    }

    .content-box {
        max-width: 800px;
        margin: 0 auto;
    }

    .content-box h2 {
        color: var(--secondary);
        margin-top: 30px;
        margin-bottom: 16px;
        font-size: 24px;
        font-weight: 700;
    }

    .content-box p {
        margin-bottom: 20px;
        color: var(--text-light);
        line-height: 1.8;
    }

    .content-box ul {
        padding-left: 20px;
        list-style: disc;
        margin-bottom: 20px;
        color: var(--text-light);
    }

    .content-box li {
        margin-bottom: 10px;
    }

    /* FAQ Style */
    .accordion-item {
        border-bottom: 1px solid #eee;
        padding: 24px 0;
    }

    .accordion-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        cursor: pointer;
        font-weight: 600;
        color: var(--secondary);
        font-size: 18px;
        transition: color 0.3s;
    }

    .accordion-header:hover {
        color: var(--primary);
    }

    .accordion-header i {
        transition: transform 0.3s;
        color: var(--text-light);
    }

    .accordion-item.active .accordion-header i {
        transform: rotate(180deg);
        color: var(--primary);
    }

    .accordion-body {
        display: none;
        margin-top: 16px;
        color: var(--text-light);
        line-height: 1.7;
    }

    .accordion-item.active .accordion-body {
        display: block;
        animation: fadeIn 0.3s;
    }

    /* Help Style */
    .contact-card {
        background: var(--bg);
        padding: 40px;
        border-radius: 20px;
        box-shadow: var(--shadow);
        margin-top: 30px;
        text-align: center;
    }

    .contact-icon {
        width: 80px;
        height: 80px;
        background: var(--primary-light);
        color: var(--primary);
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 32px;
        margin: 0 auto 20px;
    }

    .contact-card h3 {
        font-size: 24px;
        color: var(--secondary);
        margin-bottom: 10px;
    }

    .contact-card p {
        color: var(--text-light);
        margin-bottom: 24px;
    }

    /* Logged-in user badge in navbar */
    .nav-user-btn {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 10px 20px;
        border-radius: 50px;
        font-weight: 600;
        font-size: 14px;
        background: var(--gradient);
        color: #fff;
        cursor: pointer;
        transition: all .3s;
        box-shadow: 0 4px 14px rgba(16, 185, 129, .4);
        text-decoration: none;
        white-space: nowrap;
    }

    .nav-user-btn:hover {
        transform: translateY(-2px);
        box-shadow: 0 8px 25px rgba(16, 185, 129, .5);
        color: #fff;
    }

    .nav-user-btn i {
        font-size: 16px;
    }

    /* Red notification dot on mobile hamburger */
    .mobile-menu-btn {
        position: relative;
    }

    .hamburger-dot {
        display: none;
        position: absolute;
        top: -2px;
        right: -2px;
        width: 10px;
        height: 10px;
        background: #ef4444;
        border-radius: 50%;
        border: 2px solid #fff;
        animation: pulseDot 2s ease-in-out infinite;
    }

    @keyframes pulseDot {

        0%,
        100% {
            transform: scale(1);
        }

        50% {
            transform: scale(1.3);
        }
    }


    /* --- TOAST NOTIFICATIONS --- */
    .song-toast-container {
        position: fixed;
        bottom: 24px;
        right: 24px;
        z-index: 10000;
        display: flex;
        flex-direction: column;
        gap: 12px;
        pointer-events: none;
    }

    .song-toast {
        background: white;
        box-shadow: 0 10px 30px -5px rgba(0, 0, 0, 0.15);
        border-radius: 12px;
        padding: 14px 20px;
        min-width: 300px;
        max-width: 400px;
        display: flex;
        align-items: flex-start;
        gap: 14px;
        transform: translateX(120%);
        transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.4s ease;
        border-left: 4px solid #cbd5e1;
        pointer-events: auto;
        font-family: 'Outfit', sans-serif;
        opacity: 0;
    }

    .song-toast.show {
        transform: translateX(0);
        opacity: 1;
    }

    .song-toast.success {
        border-left-color: #10b981;
    }

    .song-toast.error {
        border-left-color: #ef4444;
    }

    .song-toast.warning {
        border-left-color: #f59e0b;
    }

    .song-toast.info {
        border-left-color: #3b82f6;
    }

    .song-toast-icon {
        font-size: 20px;
        margin-top: 2px;
    }

    .song-toast.success .song-toast-icon {
        color: #10b981;
    }

    .song-toast.error .song-toast-icon {
        color: #ef4444;
    }

    .song-toast.warning .song-toast-icon {
        color: #f59e0b;
    }

    .song-toast.info .song-toast-icon {
        color: #3b82f6;
    }

    .song-toast-content {
        flex: 1;
    }

    .song-toast-title {
        font-weight: 600;
        font-size: 15px;
        color: #0f172a;
        margin-bottom: 2px;
    }

    .song-toast-message {
        font-size: 14px;
        color: #64748b;
        line-height: 1.4;
    }

    .song-toast-close {
        background: none;
        border: none;
        padding: 4px;
        cursor: pointer;
        color: #94a3b8;
        transition: color 0.2s;
    }

    .song-toast-close:hover {
        color: #0f172a;
    }

    /* --- CUSTOM MODAL ALERT/CONFIRM --- */
    .custom-modal-backdrop {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(15, 23, 42, 0.6);
        backdrop-filter: blur(8px);
        z-index: 10001;
        display: flex;
        align-items: center;
        justify-content: center;
        opacity: 0;
        pointer-events: none;
        transition: opacity 0.3s ease;
    }

    .custom-modal-backdrop.active {
        opacity: 1;
        pointer-events: auto;
    }

    .custom-modal-box {
        background: white;
        width: 90%;
        max-width: 420px;
        padding: 32px;
        border-radius: 20px;
        box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
        text-align: center;
        transform: scale(0.95) translateY(10px);
        transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        font-family: 'Outfit', sans-serif;
        position: relative;
        overflow: hidden;
    }

    .custom-modal-backdrop.active .custom-modal-box {
        transform: scale(1) translateY(0);
    }

    .custom-modal-icon {
        width: 64px;
        height: 64px;
        background: #f1f5f9;
        color: #64748b;
        border-radius: 50%;
        margin: 0 auto 20px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 28px;
    }

    .custom-modal-icon.success {
        background: #ecfdf5;
        color: #10b981;
    }

    .custom-modal-icon.error {
        background: #fee2e2;
        color: #ef4444;
    }

    .custom-modal-icon.warning {
        background: #fef3c7;
        color: #f59e0b;
    }

    .custom-modal-icon.info {
        background: #dbeafe;
        color: #3b82f6;
    }

    .custom-modal-title {
        font-size: 22px;
        font-weight: 700;
        color: #0f172a;
        margin-bottom: 12px;
    }

    .custom-modal-message {
        font-size: 16px;
        color: #64748b;
        line-height: 1.6;
        margin-bottom: 28px;
    }

    .custom-modal-actions {
        display: flex;
        gap: 12px;
        justify-content: center;
    }

    .modal-btn {
        padding: 12px 24px;
        border-radius: 10px;
        font-weight: 600;
        font-size: 15px;
        cursor: pointer;
        transition: all 0.2s;
        border: none;
        font-family: inherit;
    }

    .modal-btn.primary {
        background: #10b981;
        color: white;
        flex: 1;
    }

    .modal-btn.primary:hover {
        background: #059669;
    }

    .modal-btn.secondary {
        background: #f1f5f9;
        color: #475569;
        flex: 1;
    }

    .modal-btn.secondary:hover {
        background: #e2e8f0;
        color: #0f172a;
    }

    .modal-btn.danger {
        background: #ef4444;
        color: white;
        flex: 1;
    }

    .modal-btn.danger:hover {
        background: #dc2626;
    }


/* Fix Blogger Section Wrapper for Flex Layouts */
body .main.section {
  display: contents;
}
div#main.main.section {
  display: contents;
}
.widget {
  display: contents;
}
.widget-content {
  display: contents;
}
